import React, { useState, useEffect, useRef } from 'react';
import { useAuth } from '../context/AuthContext';

const ChatPanel = ({ socket }) => {
  const [messages, setMessages] = useState([]);
  const [inputMessage, setInputMessage] = useState('');
  const [onlineCount, setOnlineCount] = useState(0);
  const messagesEndRef = useRef(null);
  const { user } = useAuth();

  // Scroll to bottom of messages
  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // Listen for messages
  useEffect(() => {
    if (socket) {
      socket.on('message', (data) => {
        setMessages(prev => [...prev, data]);
      });

      socket.on('onlineCountUpdate', (data) => {
        setOnlineCount(data.count);
      });
    }

    return () => {
      if (socket) {
        socket.off('message');
        socket.off('onlineCountUpdate');
      }
    };
  }, [socket]);

  const sendMessage = (e) => {
    e.preventDefault();
    if (inputMessage.trim() && socket) {
      const messageData = {
        id: Date.now(),
        userId: user.id,
        username: user.displayName,
        message: inputMessage,
        timestamp: new Date().toISOString()
      };

      socket.emit('sendMessage', messageData);
      setInputMessage('');
    }
  };

  const handleDeleteMessage = (messageId) => {
    if (user?.isAdmin && socket) {
      socket.emit('deleteMessage', messageId);
      setMessages(prev => prev.filter(msg => msg.id !== messageId));
    }
  };

  const handleKickUser = (userId) => {
    if (user?.isAdmin && socket) {
      socket.emit('kickUser', userId);
    }
  };

  return (
    <div className="chat-panel full-right">
      <div className="chat-header">
        <h3>Chat Room</h3>
        <span>👥 {onlineCount} online</span>
      </div>

      <div className="chat-messages">
        {messages.map((msg) => (
          <div 
            key={msg.id} 
            className={`chat-message ${msg.userId === user?.id ? 'own' : 'other'}`}
          >
            <div className="message-header">
              <strong>{msg.username}</strong>
              <small>{new Date(msg.timestamp).toLocaleTimeString()}</small>
            </div>
            <div className="message-content">{msg.message}</div>

            {user?.isAdmin && (
              <div className="admin-actions">
                <button 
                  className="btn btn-danger"
                  onClick={() => handleDeleteMessage(msg.id)}
                  style={{ fontSize: '10px', padding: '2px 4px', marginLeft: '5px' }}
                >
                  Delete
                </button>
                {msg.userId !== user.id && (
                  <button 
                    className="btn btn-danger"
                    onClick={() => handleKickUser(msg.userId)}
                    style={{ fontSize: '10px', padding: '2px 4px', marginLeft: '5px' }}
                  >
                    Kick
                  </button>
                )}
              </div>
            )}
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>

      <div className="chat-input">
        <form onSubmit={sendMessage} style={{ display: 'flex', width: '100%', gap: '5px' }}>
          <input
            type="text"
            value={inputMessage}
            onChange={(e) => setInputMessage(e.target.value)}
            placeholder="Type a message..."
            className="form-control"
          />
          <button type="submit" className="btn btn-primary">Send</button>
        </form>
      </div>
    </div>
  );
};

export default ChatPanel;
